from solution import render_notification


def test_placeholders_are_replaced():
    out = render_notification(
        "Hello {{ name }}, your order {{ order_id }} has shipped.",
        {"name": "Alice", "order_id": 1042},
    )
    assert out == "Hello Alice, your order 1042 has shipped."


def test_result_is_a_str():
    assert isinstance(render_notification("Hi {{ name }}", {"name": "Bob"}), str)


def test_spaces_inside_braces_are_optional():
    assert render_notification("{{name}}/{{ name }}/{{   name   }}", {"name": "x"}) == "x/x/x"


def test_repeated_and_adjacent_placeholders():
    out = render_notification("{{ a }}{{ a }}-{{ b }}{{ a }}", {"a": "ab", "b": "c"})
    assert out == "abab-cab"


def test_unknown_placeholder_is_empty():
    assert render_notification("Hi {{ missing }}!", {"name": "x"}) == "Hi !"
    assert render_notification("Hi {{ name }}!", {}) == "Hi !"
    assert render_notification("[{{ a }}|{{ b }}]", {"a": "1"}) == "[1|]"


def test_text_outside_placeholders_is_unchanged():
    assert render_notification("Your code has expired.", {"name": "x"}) == "Your code has expired."
    assert render_notification("", {"name": "x"}) == ""
    assert render_notification("Use {braces}, 100% of $HOME and a\\b", {}) == (
        "Use {braces}, 100% of $HOME and a\\b"
    )
