    out = render_report_header(
        "== {{ report.title }} ==\nAuthor: {{ report.author }}\nDate: {{ report.date }}", REPORT
    )
    assert out == "== Q3 Sales ==\nAuthor: Rahim\nDate: 2026-03-01"


